import pickle, csv, collections
import numpy as np
res = pickle.load(open('f3_results.pkl', 'rb'))
seeds = sorted([r for r in res if r.get('kind') == 'seed' and 'error' not in r], key=lambda r: r['seed'])
pop = [r for r in res if r.get('kind') == 'pop']
keys = list(seeds[0].keys())
with open('F3_raw.csv', 'w', newline='') as f:
    w = csv.DictWriter(f, fieldnames=keys); w.writeheader(); [w.writerow(r) for r in seeds]
sz = [r['start_size'] for r in seeds]
out = ["# F3 summary: size of the start mode, AR(1) rho=0.5, n=400, p=399, s0=4 (exact Gram), 20 seeds", "",
       "Generated by f3_report.py from f3_results.pkl; raw rows F3_raw.csv. Truths 49,149,249,349 (floor(p/8 + k p/4)), theta=(1.4,-1.0,1.8,-1.2); B = " + str(seeds[0]['B']) + ".", "",
       f"|S~0| distribution: {dict(sorted(collections.Counter(sz).items()))}; min {min(sz)}, median {np.median(sz)}, max {max(sz)}.",
       f"S0 ⊆ S~0: {sum(r['S0_in_start'] for r in seeds)}/{len(seeds)}.  |S~0 \ S0|: {dict(sorted(collections.Counter(r['n_extras'] for r in seeds).items()))}.",
       f"S~0 ⊆ Q (Q = S0 ∪ P, P = nulls within d_n = 11 of a truth, |P| = 88): {sum(r['start_in_Q'] for r in seeds)}/{len(seeds)}; extras outside P: total {sum(r['n_extras_outside_P'] for r in seeds)}.",
       f"Extras' index distance to nearest truth (per seed): " + "; ".join(f"s{r['seed']}:{r['extras_dist']}" for r in seeds if r['n_extras']) if any(r['n_extras'] for r in seeds) else "No seed has extras.",
       f"start-mode ties: n_optimal max {max(r['n_optimal'] for r in seeds)}, truncated any {any(r['truncated'] for r in seeds)}."]
if pop:
    P = pop[0]
    out += ["", f"Population margins (coded partition, P as above): TV = {P['TV']:.4g} (arg {P['TV_arg']}), NEG = {P['NEG']:.4g} (arg {P['NEG_arg']}), eta = {P['eta']:.4g}, eta_A = {P['etaA']:.4g}; blocks={P['nblocks']}, max block {P['maxblock']}, blocks with truths {P['blocks_with_truth']}, gram err {P['gram_err']:.2g}."]
open('F3_summary.md', 'w', encoding='utf-8').write("\n".join(out) + "\n"); print("\n".join(out))
